def kv_cache_gb(batch, seq_len, n_layers, n_heads, head_dim, dtype_bytes=2):
    per_token = batch * 2 * n_layers * n_heads * head_dim * dtype_bytes
    total_bytes = per_token * seq_len
    return total_bytes / (1024**3)

print("fp16, 1x4096:", f"{kv_cache_gb(1, 4096, 32, 32, 128):.3f} GB")
print("fp16, 32x2048:", f"{kv_cache_gb(32, 2048, 32, 32, 128):.3f} GB")
